import React, { useState } from 'react';
import './DataTable.css';

function DataTable({ scenario, onDataChange }) {
  const [data, setData] = useState(scenario.sampleData);
  const [editingId, setEditingId] = useState(null);

  const handlePredictionChange = (id, newPrediction) => {
    const newData = data.map(row => 
      row.id === id ? { ...row, predicted: newPrediction } : row
    );
    setData(newData);
    onDataChange(newData);
  };

  const getResultClass = (actual, predicted) => {
    if (actual === 'Positive' && predicted === 'Positive') return 'tp';
    if (actual === 'Negative' && predicted === 'Negative') return 'tn';
    if (actual === 'Negative' && predicted === 'Positive') return 'fp';
    if (actual === 'Positive' && predicted === 'Negative') return 'fn';
    return '';
  };

  const getResultLabel = (actual, predicted) => {
    if (actual === 'Positive' && predicted === 'Positive') return 'TP';
    if (actual === 'Negative' && predicted === 'Negative') return 'TN';
    if (actual === 'Negative' && predicted === 'Positive') return 'FP';
    if (actual === 'Positive' && predicted === 'Negative') return 'FN';
    return '';
  };

  return (
    <div className="data-table card">
      <h2 className="card-title">Sample Data</h2>
      <p className="card-subtitle">
        {scenario.dataDescription}
      </p>

      <div className="table-container">
        <table className="sample-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Patient/Case</th>
              <th>Actual Truth</th>
              <th>Model Prediction</th>
              <th>Result</th>
              <th>Outcome</th>
            </tr>
          </thead>
          <tbody>
            {data.map((row) => {
              const resultClass = getResultClass(row.actual, row.predicted);
              const resultLabel = getResultLabel(row.actual, row.predicted);

              return (
                <tr key={row.id} className={`table-row ${resultClass}`}>
                  <td className="cell-id">{row.id}</td>
                  <td className="cell-name">{row.name}</td>
                  <td className="cell-actual">
                    <span className={`badge ${row.actual === 'Positive' ? 'badge-positive' : 'badge-negative'}`}>
                      {row.actual}
                    </span>
                  </td>
                  <td className="cell-predicted">
                    <select
                      value={row.predicted}
                      onChange={(e) => handlePredictionChange(row.id, e.target.value)}
                      className="prediction-select"
                    >
                      <option value="Positive">Positive</option>
                      <option value="Negative">Negative</option>
                    </select>
                  </td>
                  <td className="cell-result">
                    <span className={`result-badge ${resultClass}`}>
                      {resultLabel}
                    </span>
                  </td>
                  <td className="cell-outcome">{row.outcome}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="table-legend">
        <h4>Understanding the Results:</h4>
        <div className="legend-grid">
          <div className="legend-item tp">
            <span className="legend-badge">TP</span>
            <span className="legend-text">True Positive: Correctly predicted positive</span>
          </div>
          <div className="legend-item tn">
            <span className="legend-badge">TN</span>
            <span className="legend-text">True Negative: Correctly predicted negative</span>
          </div>
          <div className="legend-item fp">
            <span className="legend-badge">FP</span>
            <span className="legend-text">False Positive: Wrongly predicted positive</span>
          </div>
          <div className="legend-item fn">
            <span className="legend-badge">FN</span>
            <span className="legend-text">False Negative: Wrongly predicted negative</span>
          </div>
        </div>
      </div>

      <div className="interaction-tip">
        <strong>Try it:</strong> Change the "Model Prediction" dropdown to see how it affects the confusion matrix and metrics below!
      </div>
    </div>
  );
}

export default DataTable;
